// 校验并登记线索；线索暂存在工作流静态数据（正式使用建议写入飞书多维表格/数据库）
const body = $input.first().json.body || $input.first().json;
const name = String(body.name || '').trim();
if (!name) return [{ json: { ok: false, error: '缺少必填字段 name' } }];
const store = $getWorkflowStaticData('global');
store.leads = store.leads || [];
const lead = { name, contact: body.contact || '', message: body.message || '', at: new Date().toISOString() };
store.leads.push(lead);
return [{ json: { ok: true, lead, totalLeads: store.leads.length,
  hint: '生产环境请把线索写入飞书多维表格/邮件通知（Pro 包 06 简历筛选就是完整链路）' } }];
